begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000631','image-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000632','image-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000631","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Image test','image-test',gen_random_uuid())::text,true);
select set_config('test.merchant',gen_random_uuid()::text,true);
select enable_zettle_pull(current_setting('test.tenant')::uuid,current_setting('test.merchant')::uuid);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentPrivate":"consignment_margin"}');
select publish_zettle_catalog_config(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'{"consignment_margin":0}');
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','image-seller@example.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Test only','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Test evidence');
select set_config('test.session',create_reception_session(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid)::text,true);
select set_config('test.photo',gen_random_uuid()::text,true);
select set_config('test.path',current_setting('test.tenant')||'/'||current_setting('test.session')||'/'||current_setting('test.photo')||'.jpg',true);
reset role;
insert into storage.objects(bucket_id,name) values('reception-photos',current_setting('test.path'));
set local role authenticated;
select save_reception_sources(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,0,jsonb_build_array(jsonb_build_object('id',current_setting('test.photo'),'kind','photo','reference',current_setting('test.path'),'observation',''),jsonb_build_object('id','f0000000-0000-4000-8000-000000000638','kind','price-evidence','reference','Staff','observation','Test appraisal')));
select publish_reception_review(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,1,null,current_setting('test.agreement')::uuid,jsonb_build_object('attributes',jsonb_build_array(jsonb_build_object('slug','description','definitionVersion',1,'value','Test jacket','sourceIds',jsonb_build_array(current_setting('test.photo')),'certainty','observed')),'price',jsonb_build_object('currency','SEK','amount','100.00','rationale','Test','sourceIds',jsonb_build_array('f0000000-0000-4000-8000-000000000638'::text)),'questions','[]'::jsonb),now()+interval '1 day');
select receive_garment(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.session')::uuid,'');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.session')::uuid,1,10000);
select is(integration_sync_preferences(current_setting('test.tenant')::uuid)->0->>'images','false','image export defaults off');
select throws_like($$select prepare_zettle_sync_image(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)$$,'%ZETTLE_IMAGES_DISABLED%','disabled settings prevent an image claim');
select set_config('test.preference',gen_random_uuid()::text,true);
select save_integration_sync_preference(current_setting('test.tenant')::uuid,current_setting('test.preference')::uuid,'paypal',current_setting('test.merchant'),null,true);
select lives_ok($$select save_integration_sync_preference(current_setting('test.tenant')::uuid,current_setting('test.preference')::uuid,'paypal',current_setting('test.merchant'),null,true)$$,'same request replays');
select throws_like($$select save_integration_sync_preference(current_setting('test.tenant')::uuid,current_setting('test.preference')::uuid,'paypal',current_setting('test.merchant'),null,false)$$,'%REQUEST_CONFLICT%','reused request cannot change meaning');
select throws_like($$select save_integration_sync_preference(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),null,false)$$,'%SYNC_SETTINGS_CHANGED%','stale tab cannot replace preference');
select throws_like($$select save_integration_sync_preference(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal','another-account',current_setting('test.preference')::uuid,false)$$,'%SYNC_CONNECTION_CHANGED%','connection binding checked');
select finish_zettle_product(current_setting('test.tenant')::uuid,prepare_zettle_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),'synced',null);
select set_config('test.request',gen_random_uuid()::text,true);
select prepare_zettle_sync_image(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.item')::uuid,current_setting('test.merchant')::uuid);
select record_zettle_image_upload(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'https://image.izettle.com/product/first.jpg');
select finish_zettle_image(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid);
select set_config('test.new_photo',gen_random_uuid()::text,true);
select set_config('test.new_path',current_setting('test.tenant')||'/'||current_setting('test.item')||'/'||current_setting('test.new_photo')||'.jpg',true);
reset role;
insert into storage.objects(bucket_id,name) values('item-photos',current_setting('test.new_path'));
set local role authenticated;
select change_item_photo(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,0,'add',current_setting('test.new_photo')::uuid);
select change_item_photo(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,1,'default',current_setting('test.new_photo')::uuid);
select is(item_sync_status(current_setting('test.tenant')::uuid,array[current_setting('test.item')::uuid])->0->'connections'->0->>'imageStatus','changed','current image differs from previously exported source');
select set_config('test.replacement',gen_random_uuid()::text,true);
select set_config('test.claim',prepare_zettle_sync_image(current_setting('test.tenant')::uuid,current_setting('test.replacement')::uuid,current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)::text,true);
select is(current_setting('test.claim')::jsonb->>'reference',current_setting('test.new_path'),'current default selected');
select is(current_setting('test.claim')::jsonb->>'bucket','item-photos','new item photos supported');
select is(current_setting('test.claim')::jsonb->>'previousUrl','https://image.izettle.com/product/first.jpg','replacement binds previous managed image');
select is(current_setting('test.claim')::jsonb->>'fresh','true','one upload grant for replacement');
select is(prepare_zettle_sync_image(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)->>'fresh','false','concurrent request cannot duplicate upload');
select record_zettle_image_upload(current_setting('test.tenant')::uuid,current_setting('test.replacement')::uuid,'https://image.izettle.com/product/second.jpg');
select is(zettle_item_image_url(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),'https://image.izettle.com/product/first.jpg','product sync preserves confirmed association while replacement pending');
select finish_zettle_image(current_setting('test.tenant')::uuid,current_setting('test.replacement')::uuid);
select is(zettle_item_image_url(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),'https://image.izettle.com/product/second.jpg','new association becomes current');
select is((select count(*) from zettle_image_intents where tenant_id=current_setting('test.tenant')::uuid),2::bigint,'old image evidence retained');
select save_integration_sync_preference(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),current_setting('test.preference')::uuid,false);
select is(zettle_item_image_url(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),'https://image.izettle.com/product/second.jpg','off preserves current image');
select throws_like($$select prepare_zettle_sync_image(current_setting('test.tenant')::uuid,current_setting('test.replacement')::uuid,current_setting('test.item')::uuid,current_setting('test.merchant')::uuid)$$,'%ZETTLE_IMAGES_DISABLED%','revocation stops a pending request');
select throws_ok($$delete from integration_sync_preference_revisions$$,'42501',null,'no direct preference writes');
select throws_like($$select komisio_private.sync_preference(current_setting('test.tenant')::uuid,'paypal')$$,'%permission denied%','private helper unavailable');
reset role;
insert into shopify_connections(tenant_id,shop_domain,shop_name,currency,cipher,connected_by) values(current_setting('test.tenant')::uuid,'synthetic.myshopify.com','Synthetic','SEK','{"iv":"test","tag":"test","data":"test"}','f0000000-0000-4000-8000-000000000631');
set local role authenticated;
select save_integration_sync_preference(current_setting('test.tenant')::uuid,gen_random_uuid(),'shopify','synthetic.myshopify.com',null,true);
select is(integration_sync_preferences(current_setting('test.tenant')::uuid)->0->>'images','false','Shopify preference does not affect PayPal');
select is(integration_sync_preferences(current_setting('test.tenant')::uuid)->1->>'images','true','independent Shopify preference');
select finish_shopify_product(current_setting('test.tenant')::uuid,prepare_shopify_product(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid),'synced',null,'gid://shopify/Product/1','gid://shopify/ProductVariant/1','gid://shopify/InventoryItem/1');
select is(prepare_shopify_sync_image(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid)->>'reference',current_setting('test.new_path'),'Shopify takes same current default');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000632","role":"authenticated"}';
select throws_like($$select integration_sync_preferences(current_setting('test.tenant')::uuid)$$,'%FORBIDDEN%','outsider cannot read preferences');
select throws_like($$select save_integration_sync_preference(current_setting('test.tenant')::uuid,gen_random_uuid(),'paypal',current_setting('test.merchant'),null,true)$$,'%FORBIDDEN%','outsider cannot set preferences');
select * from finish();rollback;
